import{_ as o}from"./chunks/tasks.pSw3Tm7x.js";import{_ as t}from"./chunks/changes.DknGkZuo.js";import{_ as a,o as r,c as n,a2 as i}from"./chunks/framework.CS-cBh1g.js";const b=JSON.parse('{"title":"A week with Mayhem","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workflow.md","filePath":"guide/workflow.md"}'),s={name:"guide/workflow.md"};function h(l,e,c,g,d,m){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="a-week-with-mayhem" tabindex="-1">A week with Mayhem <a class="header-anchor" href="#a-week-with-mayhem" aria-label="Permalink to &quot;A week with Mayhem&quot;">​</a></h1><p>Each workspace is useful alone, but they&#39;re built to work as a loop: drive the robot, collect logs, say what&#39;s wrong, let an agent (or a person) fix it, review the change by what it does, and deploy. This page follows that loop.</p><h2 id="before-the-robot-drives" tabindex="-1">Before the robot drives <a class="header-anchor" href="#before-the-robot-drives" aria-label="Permalink to &quot;Before the robot drives&quot;">​</a></h2><ul><li><strong>Pick the robot code folder</strong> once, on any page. Changes, Tasks, Robot and the Overview explainer all read it.</li><li><strong>Turn on log collection</strong> in <strong>Robot → Log collection</strong>. Mayhem pulls new <code>.wpilog</code> files off the roboRIO whenever the laptop is on the robot network. See <a href="/Mayhem/suite/robot#log-collection">Log collection</a>.</li><li><strong>Connect</strong> with your team number in <strong>Robot → Connection</strong> to see live state machines and the robot&#39;s current state. Mayhem only reads NetworkTables; it never commands the robot.</li><li>Work through <strong>Overview → Get to match-ready</strong>. Each item has a button that takes you to the fix.</li></ul><h2 id="after-a-practice-match" tabindex="-1">After a practice match <a class="header-anchor" href="#after-a-practice-match" aria-label="Permalink to &quot;After a practice match&quot;">​</a></h2><ol><li>The log arrives in <strong><a href="/Mayhem/suite/logs">Logs</a></strong> and is checked right away: brownouts, battery sag, loop overruns, disconnects and flickering signals.</li><li><strong>Robot → On the robot now</strong> shows which commit is running, whether it was deployed with uncommitted changes, and how it differs from <code>main</code>.</li><li>If something looked wrong, click its moment in the log and <strong>Comment here</strong>, or fill in the <strong>Driver form</strong> on Tasks. That feedback becomes a task pinned to that log and time.</li></ol><h2 id="fixing-it" tabindex="-1">Fixing it <a class="header-anchor" href="#fixing-it" aria-label="Permalink to &quot;Fixing it&quot;">​</a></h2><p><img src="'+o+'" alt="The Tasks board"></p><p>On <strong><a href="/Mayhem/suite/tasks">Tasks</a></strong>, feedback moves across a board:</p><ol><li><strong>New:</strong> waiting for an agent (or a teammate).</li><li><strong>Plan to approve:</strong> the agent explains, in plain English, what it&#39;ll change and how you&#39;ll see it. Approve it, or say what should be different.</li><li><strong>Ready to check:</strong> the change is done. Open it in Changes.</li></ol><p>You can skip agents entirely; the board works as a shared to-do list for the programming team too.</p><h2 id="reviewing-the-change" tabindex="-1">Reviewing the change <a class="header-anchor" href="#reviewing-the-change" aria-label="Permalink to &quot;Reviewing the change&quot;">​</a></h2><p><img src="'+t+'" alt="The Changes summary"></p><p><strong><a href="/Mayhem/suite/changes">Changes</a></strong> compares two versions of the robot code by behavior: driver controls, state machines, values, hardware and autos. A red chip means a safety change, such as a CAN ID, current limit, motor direction or gear ratio. Run the <strong>sim proof</strong> to build both versions, press every button, run every auto and your team&#39;s scenarios, and replay any difference.</p><p>Accept the change, or send it back with a note saying what&#39;s wrong.</p><h2 id="at-competition" tabindex="-1">At competition <a class="header-anchor" href="#at-competition" aria-label="Permalink to &quot;At competition&quot;">​</a></h2><ul><li>Keep <code>main</code> as the known-good version. If the robot is running something else and it misbehaves, <strong>Robot → On the robot now → Put main back on the robot</strong> builds and deploys <code>main</code> (robot connected and disabled).</li><li>Use pit notes for anything quick: &quot;left intake roller rubbing the frame&quot;.</li><li>Upload logs to the team site from <strong>Robot → Log collection → Team upload</strong> so the whole team can open them.</li></ul>',17)])])}const w=a(s,[["render",h]]);export{b as __pageData,w as default};
